            0,
            abi.encodeWithSignature(
                "transfer(address,uint256)",
                msg.sender,
                _balance
            )
        );
    }

    function claimRewards() external {
        require(strategies[msg.sender], "!strategy");

        uint256 _before = IERC20(snx).balanceOf(address(crvLocker));
